export const FEATURE_COUNT = FEATURE_CATALOG.length;

export const MODULE_METADATA = Object.fromEntries(
  [...new Set(FEATURE_CATALOG.map((feature) => feature.module))].map((code) => {
    const first = FEATURE_CATALOG.find((feature) => feature.module === code);
    const count = FEATURE_CATALOG.filter((feature) => feature.module === code).length;
    return [code, { name: first?.moduleName ?? `Module ${code}`, count }];
  })
) as Record<string, { name: string; count: number }>;

export const MODULE_RANGE = `Modules ${Object.keys(MODULE_METADATA).join("–")}`;

export function getFeatureById(featureId: string) {
  const normalized = featureId.trim().toUpperCase();
  return FEATURE_CATALOG.find((feature) => feature.id === normalized);
}
